paragraph.math:
$$\begin{array}{l}
  {{\int{x\sin xdx}} = {f(x)g(x) - {\int{g(x)f^{\prime}(x)dx}}}} \\
  {\phantom{\int{x\sin xdx}} = {x\left( {- \cos x} \right) - {\int{\left( {- \cos x} \right)dx}}}} \\
  {\phantom{\int{x\sin xdx}} = {- x\cos x + {\int{\cos xdx}}}} \\
  {\phantom{\int{x\sin xdx}} = {- x\cos x + \sin x + C}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int l}nxdx} = {x\ln x - {\int{x \cdot \frac{1}{x}{dx}}}}} \\
  {\phantom{{\int l}nxdx} = {x\ln x - {\int{dx}}}} \\
  {\phantom{{\int l}nxdx} = {x\ln x - x + C}}
  \end{array}$$

$$\begin{array}{l}
  {\int{te^{ t}dt = te^{ t} - {\int{e^{ t}dt}}}} \\
  {\phantom{\int{te^{ t}dt}}{= te^{ t} - e^{ t} + C}}
  \end{array}$$

$$\begin{array}{l}
  {{\int t^{2}}e^{ t}dt = {t^{2}e^{ t} - 2{\int{te^{ t}dt}}}} \\
  {\phantom{{\int t^{2}}e^{ t}dt} = {t^{2}e^{ t} - 2{({te^{ t} - e^{ t} + C})}}} \\
  {\phantom{{\int t^{2}}e^{ t}dt} = {t^{2}e^{ t} - 2te^{ t} + 2e^{ t} + C_{1}\qquad{where}C_{1} = - 2C}}
  \end{array}$$
